// Minimal Cosmic Dodger game targeting <canvas id="game">
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = canvas.clientWidth || 800;
canvas.height = canvas.clientHeight || 600;

// Ship
const ship = {x: 100, y: canvas.height/2, w: 30, h: 20, speed: 4};
const keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup', e => keys[e.key] = false);

// Debris
const debris = [];
let debrisTimer = 0;
const spawnDebris = () => {
  const size = Math.random()*30+10;
  const side = Math.random()<0.5?'left':'right';
  const y = Math.random()*canvas.height;
  const x = side==='left' ? -size : canvas.width+size;
  const vx = side==='left' ? (2+Math.random()*3) : -(2+Math.random()*3);
  const vy = (Math.random()-0.5)*2;
  debris.push({x, y, w:size, h:size, vx, vy});
};

// Starfield background
const stars = [];
for(let i=0;i<100;i++){
  stars.push({x:Math.random()*canvas.width, y:Math.random()*canvas.height, r:Math.random()*2+1, speed:0.5+Math.random()});
}

let distance = 0;
let gameOver = false;

function update(){
  // move ship
  if(keys['ArrowUp']||keys['w']) ship.y -= ship.speed;
  if(keys['ArrowDown']||keys['s']) ship.y += ship.speed;
  if(keys['ArrowLeft']||keys['a']) ship.x -= ship.speed;
  if(keys['ArrowRight']||keys['d']) ship.x += ship.speed;
  // keep within bounds
  ship.x = Math.max(0, Math.min(canvas.width-ship.w, ship.x));
  ship.y = Math.max(0, Math.min(canvas.height-ship.h, ship.y));

  // stars move left to simulate forward motion
  stars.forEach(s=>{s.x -= s.speed; if(s.x<0) s.x = canvas.width;});

  // spawn debris every 60 frames (~1s at 60fps)
  if(debrisTimer-- <= 0){
    spawnDebris();
    debrisTimer = 60;
  }

  // update debris
  for(let i=debris.length-1;i>=0;i--){
    const d = debris[i];
    d.x += d.vx; d.y += d.vy;
    // remove when offscreen
    if(d.x < -d.w || d.x > canvas.width+ d.w) debris.splice(i,1);
    // collision
    if(!(ship.x + ship.w < d.x || ship.x > d.x + d.w || ship.y + ship.h < d.y || ship.y > d.y + d.h)){
      gameOver = true;
    }
  }

  distance += 0.1; // arbitrary distance unit per frame
}

function draw(){
  ctx.clearRect(0,0,canvas.width,canvas.height);
  // stars
  ctx.fillStyle = '#fff';
  stars.forEach(s=>{ctx.beginPath(); ctx.arc(s.x,s.y,s.r,0,Math.PI*2); ctx.fill();});

  // ship (triangle)
  ctx.fillStyle = '#0f0';
  ctx.beginPath();
  ctx.moveTo(ship.x, ship.y + ship.h/2);
  ctx.lineTo(ship.x + ship.w, ship.y);
  ctx.lineTo(ship.x + ship.w, ship.y + ship.h);
  ctx.closePath();
  ctx.fill();

  // debris
  ctx.fillStyle = '#f00';
  debris.forEach(d=>{ctx.fillRect(d.x,d.y,d.w,d.h);});

  // HUD
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText('Distance: '+Math.floor(distance),10,20);
  if(gameOver){
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(0,0,canvas.width,canvas.height);
    ctx.fillStyle = '#fff';
    ctx.textAlign = 'center';
    ctx.font = '48px sans-serif';
    ctx.fillText('Game Over', canvas.width/2, canvas.height/2-20);
    ctx.font = '24px sans-serif';
    ctx.fillText('Travelled: '+Math.floor(distance)+' units', canvas.width/2, canvas.height/2+20);
  }
}

function loop(){
  if(!gameOver){
    update();
    draw();
    requestAnimationFrame(loop);
  } else {
    draw(); // final frame with overlay
  }
}

// start
requestAnimationFrame(loop);
